1	/**
2	 * `nexus worktree copy-ignored` (WP-1311): share build caches between worktrees.
3	 *
4	 * Default source set: files that are both git-ignored and matched by the source checkout's `.worktreeinclude`
5	 * (gitignore syntax). `--all-ignored` copies every ignored file instead and says so, because that can carry secrets
6	 * such as `.env` into each worktree. Copies use `COPYFILE_FICLONE` (reflink where the file system has it, a plain copy
7	 * otherwise), keep modification times so incremental builds do not start over, never overwrite without `--force`, and
8	 * never follow or create a link that leaves the tree.
9	 *
10	 * Residual race: a source file replaced by a link between the planning walk and its copy would be read through the
11	 * link. The source is the operator's own checkout, not a path an untrusted party can race; destination directories are
12	 * checked component by component, files are created exclusively, and a `--force` replacement is staged beside its
13	 * destination and renamed into place, so a failed copy never removes the file it was meant to replace.
14	 */
15	import { randomUUID } from "node:crypto";
16	import * as fs from "node:fs";
17	import * as path from "node:path";
18	import { redactSecrets } from "../ui.js";
19	import { mkdirVerified, SafePathError } from "../safe_fs.js";
20	import { findEntry, shownPath, WorktreeError, type CommandResult, type WorktreeContext } from "./core.js";
21	import { git } from "./git.js";
22	import { currentEntry, openRepo } from "./repo.js";
23	
24	export interface CopyLimits { maxFiles: number; maxBytes: number }
25	
26	export const DEFAULT_COPY_LIMITS: CopyLimits = { maxFiles: 50_000, maxBytes: 4 * 1024 ** 3 };
27	export const defaultCopyLimits: { current: CopyLimits } = { current: { ...DEFAULT_COPY_LIMITS } };
28	
29	export interface CopyOptions {
30	  from?: string;
31	  to?: string;
32	  force?: boolean;
33	  dryRun?: boolean;
34	  allIgnored?: boolean;
35	  limits?: CopyLimits;
36	}
37	
38	const NEVER_COPY = new Set([".git", ".nexus", ".entire"]);
39	const INCLUDE_FILE = ".worktreeinclude";
40	const REPORT_LINES = 20;
41	
42	type Op =
43	  | { kind: "dir"; rel: string }
44	  | { kind: "file"; rel: string; root: string; size: number; atimeMs: number; mtimeMs: number }
45	  | { kind: "symlink"; rel: string; root: string; target: string };
46	
47	const virtualenv = (rel: string) => `${rel}: virtualenv (absolute paths; recreate it in the worktree)`;
48	
49	/** The directories above `rel` (relative, nearest last), excluding the tree root. */
50	function ancestors(rel: string): string[] {
51	  const out: string[] = [];
52	  for (let dir = path.dirname(rel); dir !== "." && dir !== "/"; dir = path.dirname(dir)) out.unshift(dir);
53	  return out;
54	}
55	
56	function insideOrEqual(parent: string, child: string): boolean {
57	  const rel = path.relative(parent, child);
58	  return rel === "" || (!rel.startsWith("..") && !path.isAbsolute(rel));
59	}
60	
61	class CopyLimitError extends Error {}
62	
63	export function copyIgnored(ctx: WorktreeContext, options: CopyOptions = {}): CommandResult {
64	  try {
65	    return copyIgnoredUnchecked(ctx, options);
66	  } catch (err) {
67	    if (err instanceof CopyLimitError) return { success: false, output: err.message };
68	    throw err;
69	  }
70	}
71	
72	function copyIgnoredUnchecked(ctx: WorktreeContext, options: CopyOptions): CommandResult {
73	  const limits = options.limits ?? defaultCopyLimits.current;
74	  const repo = openRepo(ctx.cwd);
75	  const source = options.from ? findEntry(repo, options.from, ctx.home) : repo.entries[0];
76	  const dest = options.to ? findEntry(repo, options.to, ctx.home) : currentEntry(repo);
77	  if (!dest) throw new WorktreeError("no destination worktree: run from inside one or pass --to <branch|path>");
78	  const sourceRoot = fs.realpathSync(source.path);
79	  const destRoot = fs.realpathSync(dest.path);
80	  if (sourceRoot === destRoot) throw new WorktreeError("source and destination are the same worktree; pass --from and/or --to");
81	
82	  const selection = listRoots(sourceRoot, options.allIgnored === true);
83	  if (selection === "no-include") {
84	    return { success: true, output: `Nothing to copy: ${INCLUDE_FILE} is missing in the source worktree (add it, or pass --all-ignored).`, data: { copied: 0 } };
85	  }
86	  const { roots, only } = selection;
87	
88	  // Nested worktrees of this repository must never be walked into.
89	  const nested = repo.entries.map((entry) => { try { return fs.realpathSync(entry.path); } catch { return ""; } }).filter((p) => p && p !== sourceRoot && insideOrEqual(sourceRoot, p));
90	
91	  const ops: Op[] = [];
92	  const skipped: string[] = [];
93	  let files = 0;
94	  let bytes = 0;
95	
96	  const walk = (rel: string, root: string): void => {
97	    const abs = path.join(sourceRoot, rel);
98	    if (nested.some((n) => insideOrEqual(n, abs))) { skipped.push(`${rel}: nested worktree`); return; }
99	    if (NEVER_COPY.has(path.basename(rel))) return;
100	    const stat = fs.lstatSync(abs);
101	    if (only && !(stat.isDirectory() ? only.dirs.has(rel) : only.files.has(rel))) return;
102	    if (stat.isSymbolicLink()) {
103	      const target = fs.readlinkSync(abs);
104	      // Resolve through the real file system, not lexically: `self -> .` followed by `self/../..` leaves the tree although
105	      // the normalised text stays inside. A target that cannot be resolved (dangling) is not copied either.
106	      let real: string | undefined;
107	      try { real = fs.realpathSync(`${fs.realpathSync(path.dirname(abs))}${path.sep}${target}`); } catch { real = undefined; }
108	      if (path.isAbsolute(target) || real === undefined || !insideOrEqual(sourceRoot, real)) { skipped.push(`${rel}: symbolic link leaves the tree`); return; }
109	      count(0);
110	      ops.push({ kind: "symlink", rel, root, target });
111	      return;
112	    }
113	    if (stat.isDirectory()) {
114	      if (fs.existsSync(path.join(abs, "pyvenv.cfg"))) { skipped.push(virtualenv(rel)); return; }
115	      ops.push({ kind: "dir", rel });
116	      for (const child of fs.readdirSync(abs)) walk(path.join(rel, child), root);
117	      return;
118	    }
119	    if (!stat.isFile()) { skipped.push(`${rel}: not a regular file`); return; }
120	    count(stat.size);
121	    ops.push({ kind: "file", rel, root, size: stat.size, atimeMs: stat.atimeMs, mtimeMs: stat.mtimeMs });
122	  };
123	  const count = (size: number): void => {
124	    files++;
125	    bytes += size;
126	    if (files > limits.maxFiles) throw new CopyLimitError(`refusing to copy: more than ${limits.maxFiles} files match (file limit); narrow ${INCLUDE_FILE}`);
127	    if (bytes > limits.maxBytes) throw new CopyLimitError(`refusing to copy: the files exceed the ${limits.maxBytes} byte limit; narrow ${INCLUDE_FILE}`);
128	  };
129	
130	  for (const entry of roots) {
131	    const rel = entry.replace(/\/$/, "");
132	    if (!rel || path.isAbsolute(rel) || rel.split("/").includes("..") || rel.split("/").some((part) => NEVER_COPY.has(part))) continue;
133	    // A root can be a single file deep inside a directory the walk never visits (`.venv/bin/activate`): the
134	    // virtualenv exclusion must hold for its ancestors too.
135	    const env = ancestors(rel).find((dir) => fs.existsSync(path.join(sourceRoot, dir, "pyvenv.cfg")));
136	    if (env !== undefined) { if (!skipped.includes(virtualenv(env))) skipped.push(virtualenv(env)); continue; }
137	    walk(rel, rel);
138	  }
139	
140	  const lines: string[] = [];
141	  let copied = 0;
142	  let existing = 0;
143	  let plannedBytes = 0;
144	
145	  // One plan for the preview and the real run, so the two cannot diverge. Nothing here writes.
146	  const tracked = ops.some((op) => op.kind !== "dir") ? new Set(nul(git(destRoot, ["ls-files", "-z", "--cached"]).stdout)) : new Set<string>();
147	  const unsafe = (rel: string, problem: string) => `${rel}: destination is not safe (${problem})`;
148	  // Submodules of the destination (gitlinks in its index): nothing is written at or below them.
149	  const gitlinks = new Set(nul(git(destRoot, ["ls-files", "-s", "-z"]).stdout).filter((line) => line.startsWith("160000 ")).map((line) => line.slice(line.indexOf("\t") + 1)));
150	  const insideGitlink = (rel: string): boolean => [...gitlinks].some((g) => rel === g || rel.startsWith(g + path.sep));
151	  /**
152	   * The first problem with the path to `rel` under the destination, if any: an ancestor (or, for a directory, the entry
153	   * itself) that is a link or a file, a submodule, or a nested repository. Missing ancestors are fine: they get created.
154	   */
155	  const ancestryProblem = (rel: string, includeSelf = false): string | undefined => {
156	    if (insideGitlink(rel)) return "inside a submodule of the destination";
157	    const parts = (includeSelf ? rel : path.dirname(rel)).split(path.sep).filter((p) => p && p !== ".");
158	    let current = destRoot;
159	    for (const part of parts) {
160	      current = path.join(current, part);
161	      const stat = fs.lstatSync(current, { throwIfNoEntry: false });
162	      if (!stat) return undefined;
163	      if (stat.isSymbolicLink()) return "a symbolic link in the way";
164	      if (!stat.isDirectory()) return "a file in the way";
165	      if (fs.lstatSync(path.join(current, ".git"), { throwIfNoEntry: false })) return "inside a nested repository of the destination";
166	    }
167	    return undefined;
168	  };
169	  /**
170	   * Whether the link `rel -> target` would resolve inside the destination, walking the destination's real layout: a
171	   * directory the source has as a real directory can be a link out of the worktree there (also one that is kept).
172	   */
173	  const linkStaysInside = (rel: string, target: string): boolean => {
174	    let current = path.join(destRoot, path.dirname(rel)); // its ancestors were verified to be real directories
175	    for (const part of target.split("/")) {
176	      if (!part || part === ".") continue;
177	      current = part === ".." ? path.dirname(current) : path.join(current, part);
178	      const stat = fs.lstatSync(current, { throwIfNoEntry: false });
179	      if (stat?.isSymbolicLink()) {
180	        try { current = fs.realpathSync(current); } catch { return false; }
181	      }
182	      if (!insideOrEqual(destRoot, current)) return false;
183	    }
184	    return true;
185	  };
186	  type Step = { op: Exclude<Op, { kind: "dir" }>; replace: boolean };
187	  const steps: Step[] = [];
188	  const dirs: string[] = [];
189	  const blocked: string[] = [];
190	  for (const op of ops) {
191	    if (blocked.some((b) => op.rel === b || op.rel.startsWith(b + path.sep))) continue;
192	    const problem = ancestryProblem(op.rel, op.kind === "dir");
193	    if (problem) {
194	      skipped.push(unsafe(op.rel, problem));
195	      if (op.kind === "dir") blocked.push(op.rel);
196	      continue;
197	    }
198	    if (op.kind === "dir") { dirs.push(op.rel); continue; }
199	    if (op.kind === "symlink" && !linkStaysInside(op.rel, op.target)) { skipped.push(`${op.rel}: symbolic link leaves the tree in the destination`); continue; }
200	    if (tracked.has(op.rel)) { skipped.push(`${op.rel}: tracked in destination (never overwritten, even with --force)`); continue; }
201	    const present = fs.lstatSync(path.join(destRoot, op.rel), { throwIfNoEntry: false });
202	    if (present) {
203	      if (!options.force) { existing++; continue; }
204	      if (!present.isFile() && !present.isSymbolicLink()) { skipped.push(`${op.rel}: a directory is in the way`); continue; }
205	      const me = process.getuid?.();
206	      if (me !== undefined && present.uid !== me) { skipped.push(unsafe(op.rel, `owned by uid ${present.uid}, not ${me}`)); continue; }
207	    }
208	    steps.push({ op, replace: Boolean(present) });
209	    plannedBytes += op.kind === "file" ? op.size : 0;
210	  }
211	
212	  if (options.dryRun) {
213	    const pending = new Map<string, number>();
214	    for (const { op } of steps) pending.set(op.root, (pending.get(op.root) ?? 0) + 1);
215	    for (const [root, n] of pending) lines.push(`would copy ${shownPath(ctx.home, root)} (${n} file${n === 1 ? "" : "s"})`);
216	    copied = steps.length;
217	  } else {
218	    // Directories already proven to be real, user-owned entries under the destination: each is verified once, and any
219	    // staging file a killed run left in it is removed.
220	    const ensured = new Set<string>([destRoot]);
221	    sweepStaging(destRoot);
222	    const ensureDir = (dir: string): string | undefined => {
223	      if (ensured.has(dir)) return undefined;
224	      try {
225	        mkdirVerified(destRoot, dir);
226	      } catch (err) {
227	        if (err instanceof SafePathError) return err.message;
228	        throw err;
229	      }
230	      sweepStaging(dir);
231	      ensured.add(dir);
232	      return undefined;
233	    };
234	    for (const dir of dirs) {
235	      const problem = ensureDir(path.join(destRoot, dir));
236	      if (problem) skipped.push(unsafe(dir, problem.includes("symbolic link") ? "a symbolic link in the way" : problem.replace(destRoot, "")));
237	    }
238	    for (const { op, replace } of steps) {
239	      const dst = path.join(destRoot, op.rel);
240	      // A file or link selected on its own has no directory operation above it: its parents are created and verified here.
241	      const parentProblem = ensureDir(path.dirname(dst));
242	      if (parentProblem) { skipped.push(unsafe(op.rel, parentProblem.includes("symbolic link") ? "a symbolic link in the way" : parentProblem.replace(destRoot, ""))); continue; }
243	      // Always stage under a temporary name in the same directory: a run killed mid-copy leaves a `.nexus-copy-*.tmp`
244	      // (swept by the next run), never a truncated file under its final name. A new entry is linked into place, which
245	      // cannot replace anything; a replaced entry is renamed over.
246	      const staged = path.join(path.dirname(dst), `.nexus-copy-${process.pid}-${randomUUID()}.tmp`);
247	      try {
248	        place(sourceRoot, op, staged);
249	        if (replace) {
250	          fs.renameSync(staged, dst);
251	        } else {
252	          try {
253	            fs.linkSync(staged, dst);
254	          } catch (err: any) {
255	            if (err?.code !== "EEXIST") throw err;
256	            existing++; // it appeared since the plan: kept
257	            continue;
258	          } finally {
259	            try { fs.unlinkSync(staged); } catch { /* already renamed or gone */ }
260	          }
261	        }
262	      } catch (err) {
263	        try { fs.unlinkSync(staged); } catch { /* never created */ }
264	        throw err;
265	      }
266	      copied++;
267	    }
268	  }
269	
270	  const head = options.dryRun
271	    ? `Dry run: ${copied} file(s), ${plannedBytes} byte(s) would be copied from ${shownPath(ctx.home, sourceRoot)} to ${shownPath(ctx.home, destRoot)}`
272	    : `Copied ${copied} file(s) (${plannedBytes} byte(s) planned) from ${shownPath(ctx.home, sourceRoot)} to ${shownPath(ctx.home, destRoot)}`;
273	  const out = [head, ...lines];
274	  if (existing) out.push(`kept ${existing} existing file(s) (use --force to overwrite)`);
275	  for (const note of skipped.slice(0, REPORT_LINES)) out.push(`skipped ${redactSecrets(note)}`);
276	  if (skipped.length > REPORT_LINES) out.push(`... ${skipped.length - REPORT_LINES} more skipped`);
277	  if (options.allIgnored) out.push("warning: --all-ignored copies every ignored file, including secrets such as .env, into the destination");
278	  return { success: true, output: out.join("\n"), data: { copied, planned: files, bytes, skipped: skipped.length, existing } };
279	}
280	
281	/**
282	 * Removes staging files (`.nexus-copy-<pid>-<uuid>.tmp`) that a killed earlier run left in `dir`: only regular files and
283	 * links owned by this user, and only when their owner process is gone. A running copy's staging file is never touched.
284	 */
285	function sweepStaging(dir: string): void {
286	  const me = process.getuid?.();
287	  let names: string[];
288	  try { names = fs.readdirSync(dir); } catch { return; }
289	  for (const name of names) {
290	    const match = /^\.nexus-copy-(\d+)-[0-9a-f-]{36}\.tmp$/.exec(name);
291	    if (!match) continue;
292	    const file = path.join(dir, name);
293	    try {
294	      const stat = fs.lstatSync(file);
295	      if (!(stat.isFile() || stat.isSymbolicLink()) || (me !== undefined && stat.uid !== me)) continue;
296	      let ownerGone: boolean;
297	      try { process.kill(Number(match[1]), 0); ownerGone = false; } catch (err: any) { ownerGone = err?.code === "ESRCH"; }
298	      if (ownerGone) fs.unlinkSync(file);
299	    } catch { /* raced with another run */ }
300	  }
301	}
302	
303	/** Creates the entry for `op` at `at`, exclusively (never through a link), with the source's modification time. */
304	function place(sourceRoot: string, op: Exclude<Op, { kind: "dir" }>, at: string): void {
305	  if (op.kind === "symlink") {
306	    fs.symlinkSync(op.target, at);
307	    return;
308	  }
309	  fs.copyFileSync(path.join(sourceRoot, op.rel), at, fs.constants.COPYFILE_FICLONE | fs.constants.COPYFILE_EXCL);
310	  fs.utimesSync(at, op.atimeMs / 1000, op.mtimeMs / 1000);
311	}
312	
313	/**
314	 * What to copy, from Git's own ignore evaluation: `roots` are the top-level entries (files, or directories with a
315	 * trailing slash) the walk starts from and the report groups by; `only`, when set, is the exact set of files and links
316	 * selected plus the directories above them, and the walk copies nothing outside it.
317	 */
318	interface Selection { roots: string[]; only?: { files: Set<string>; dirs: Set<string> } }
319	
320	function listRoots(sourceRoot: string, all: boolean): Selection | "no-include" {
321	  const base = ["ls-files", "-z", "--others", "--ignored"];
322	  if (all) return { roots: nul(git(sourceRoot, [...base, "--directory", "--exclude-standard"]).stdout) };
323	  const file = path.join(sourceRoot, INCLUDE_FILE);
324	  const stat = fs.lstatSync(file, { throwIfNoEntry: false });
325	  if (!stat) return "no-include";
326	  if (!stat.isFile() || stat.size > 64 * 1024) throw new WorktreeError(`${INCLUDE_FILE} must be a regular file of at most 64 KiB`);
327	  // The intersection is taken file by file: a directory that the include file lists as a whole (`cache/`) is not
328	  // itself ignored when `.gitignore` only matches files inside it (`*.o`), so a collapsed entry would be dropped.
329	  const included = nul(git(sourceRoot, [...base, `--exclude-from=${file}`]).stdout);
330	  const files = new Set(included.length === 0 ? [] : nul(git(sourceRoot, ["check-ignore", "-z", "--stdin"], { input: included.join("\0") + "\0", allowFailure: true }).stdout));
331	  const dirs = new Set<string>();
332	  for (const rel of files) for (const dir of ancestors(rel)) dirs.add(dir);
333	  if (files.size === 0) return { roots: [], only: { files, dirs } };
334	  // Collapsed entries group the report; keep those that are selected or have a selected file beneath them.
335	  const collapsed = nul(git(sourceRoot, [...base, "--directory", `--exclude-from=${file}`]).stdout);
336	  return { roots: collapsed.filter((entry) => { const rel = entry.replace(/\/$/, ""); return files.has(rel) || dirs.has(rel); }), only: { files, dirs } };
337	}
338	
339	function nul(text: string): string[] {
340	  return text.split("\0").filter(Boolean);
341	}
