181	 * so a lock is stale only when its holder is gone (a dead pid on this host) or it is far older than any checkout.
182	 * A pid from another PID namespace (a container, `unshare`) reads as gone here, so the age rule is the only guard
183	 * against a holder in another namespace; see docs/WORKTREES.md.
184	 */
185	function staleLockIdentity(lock: string): fs.BigIntStats | undefined {
186	  const stat = fs.lstatSync(lock, { bigint: true });
187	  let pid = NaN;
188	  try { pid = Number.parseInt(fs.readFileSync(lock, "utf8").trim(), 10); } catch { /* unreadable: judge by age */ }
189	  if (Number.isSafeInteger(pid) && pid > 0 && pid !== process.pid) {
190	    try {
191	      process.kill(pid, 0);
192	    } catch (err: any) {
193	      if (err?.code === "ESRCH") return stat; // the holder is gone
194	    }
