198	  // covers the writer; after that nobody is coming, so waiting out the full ten minutes would only block everyone.
199	  const unreadable = !(Number.isSafeInteger(pid) && pid > 0);
200	  return age > (unreadable ? Math.min(lockSettings.unreadableGraceMs, lockSettings.staleMs) : lockSettings.staleMs) ? stat : undefined;
