1	/**
2	 * The one place the worktree feature runs Git.
3	 *
4	 * Every call pins the configuration that could otherwise turn a repository into code execution or change what a
5	 * result means: no replace objects, no hooks (`core.hooksPath` plus the Git 2.54+ configured-hook switch), no
6	 * fsmonitor, no external transport helpers, no inherited repository-selecting environment. Refs and paths that
7	 * come from a user are passed after `--end-of-options`; callers also validate them first (see paths.ts), so a
8	 * name such as `--upload-pack=...` is refused before it reaches Git.
9	 *
10	 * Trust boundary: the agent's sandbox can write its worktree, `.git` pointer and nested repositories included, so
11	 * `git()` first refuses a checkout whose `.git` leads anywhere the agent could have planted (`untrustedCheckoutReason`),
12	 * and then runs Git against the VERIFIED git directory (`--git-dir`/`--work-tree`), so a pointer rewritten after the
13	 * check is never re-read. Past that, `.git/config`, the user's and the system's Git configuration are trusted as Git trusts them. Hooks,
14	 * fsmonitor and external transports are pinned off because a checkout can reach them, but a `filter.<name>.clean`
15	 * command configured in that trusted configuration still runs when `git status` compares content; `.gitattributes`
16	 * can only name a filter, never define its command.
17	 */
18	import { spawnSync } from "node:child_process";
19	import * as fs from "node:fs";
20	import * as path from "node:path";
21	import { envWithoutConfiguredHooks } from "../core/git_hook_guard.js";
22	import { PATHSPEC_MODE_ENV, parseSubmoduleStatus, untrustedCheckoutReason, verifyCheckout } from "../core/checkout_trust.js";
23	export { parseSubmoduleStatus, untrustedCheckoutReason };
24	import { redactSecrets } from "../ui.js";
25	
26	/** Hook events Nexus-initiated worktree commands must never fire. */
27	export const SUPPRESSED_HOOK_EVENTS = [
28	  "post-checkout", "pre-commit", "prepare-commit-msg", "commit-msg", "post-commit", "post-merge",
29	  "pre-merge-commit", "pre-rebase", "post-rewrite", "reference-transaction", "post-index-change", "pre-auto-gc",
30	] as const;
31	
32	export const PINNED_GIT_FLAGS: readonly string[] = [
33	  "--no-replace-objects",
34	  "--no-optional-locks",
35	  "-c", "core.hooksPath=/dev/null",
36	  "-c", "core.fsmonitor=false",
37	  "-c", "protocol.ext.allow=never",
38	  "-c", "submodule.recurse=false",
39	  "-c", "core.quotePath=false",
40	];
41	
42	/** Variables that would redirect Git at another repository, object store, diff driver or ref namespace, or change how pathspecs are read. */
43	export const SCRUBBED_ENV = [
44	  "GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY", "GIT_ALTERNATE_OBJECT_DIRECTORIES",
45	  "GIT_COMMON_DIR", "GIT_NAMESPACE", "GIT_EXTERNAL_DIFF", "GIT_REPLACE_REF_BASE", "GIT_PAGER", "GIT_SSH_COMMAND",
46	  "GIT_ASKPASS", "GIT_EDITOR", "GIT_SEQUENCE_EDITOR", "GIT_PREFIX", "GIT_CEILING_DIRECTORIES",
47	  ...PATHSPEC_MODE_ENV,
48	];
49	
50	export class GitError extends Error {
51	  constructor(message: string, readonly status: number | null, readonly args: readonly string[]) {
52	    super(message);
53	    this.name = "GitError";
54	  }
55	}
56	
57	/**
58	 * Text that may carry bytes from the agent's worktree (a path, Git's own error line) shown with control, C1, bidi and
59	 * line-separator characters escaped, never raw: they would otherwise reach the operator's terminal as escape sequences.
60	 */
61	export function printable(text: string): string {
62	  return text.replace(/[\u0000-\u001f\u007f-\u009f\u061c\u200e\u200f\u2028\u2029\u202a-\u202e\u2066-\u2069]/g, (c) => `\\u${c.charCodeAt(0).toString(16).padStart(4, "0")}`);
63	}
64	
65	/** A checkout (or a repository nested in one) whose Git directory the sandboxed agent could have planted. */
66	export class UntrustedCheckoutError extends GitError {
67	  constructor(cwd: string, reason: string, args: readonly string[]) {
68	    super(`refusing to run Git in ${printable(cwd)}: it is not a trusted worktree of this repository (${printable(reason)})`, null, args);
69	    this.name = "UntrustedCheckoutError";
70	  }
71	}
72	
73	export interface GitResult { status: number | null; stdout: string; stderr: string; timedOut: boolean }
74	
75	export interface GitOptions {
76	  /** Milliseconds before the child is killed (default 30 s). */
77	  timeoutMs?: number;
78	  /** Do not throw on a non-zero exit. */
79	  allowFailure?: boolean;
80	  /** Extra environment (applied after scrubbing); never the repository selectors. */
81	  env?: Record<string, string>;
82	  maxBuffer?: number;
83	  /** Text for the child's standard input (for `--stdin` forms). */
84	  input?: string;
85	}
86	
87	/** Submodule levels `nestedRepositoryReason` walks before refusing rather than guessing. */
88	const MAX_SUBMODULE_DEPTH = 4;
89	/** Entries read in untracked directories while looking for a planted repository, and the size of a file listing. */
90	const MAX_UNTRACKED_ENTRIES_SCANNED = 100_000;
91	const LISTING_BUFFER = 256 * 1024 * 1024;
92	
93	/**
94	 * Whether a repository the agent could have planted sits below `dir`: a gitlink in the index or an untracked directory
95	 * holding a `.git`. Git itself descends into submodules when it reports status, reading their configuration, so this
96	 * runs before every status. Undefined when `dir` is not an agent-writable checkout or nothing is wrong.
97	 */
98	export function nestedRepositoryReason(dir: string, depth = 0): string | undefined {
99	  const own = verifyCheckout(dir);
100	  if (own.reason) return own.reason;
101	  if (!own.gitDir) return undefined;
102	  if (depth > MAX_SUBMODULE_DEPTH) return `submodules are nested more than ${MAX_SUBMODULE_DEPTH} levels deep below ${dir}`;
103	  const candidates = new Set<string>();
104	  // Large trees: the listings can be long, and one that does not fit is a refusal, not a pass.
105	  const listing = (args: string[]) => git(dir, args, { maxBuffer: LISTING_BUFFER }).stdout.split("\0");
106	  // Paths are decoded as UTF-8: bytes that are not valid become U+FFFD and name nothing on disk, so a gitlink or a
107	  // directory with such a name could hide a planted repository from this check while Git still descends into it. Those
108	  // are refused, not skipped; an ordinary file with such a name is fine.
109	  const undecodable = (name: string) => name.includes("\uFFFD");
110	  for (const entry of listing(["ls-files", "-s", "-z"])) {
111	    const tab = entry.indexOf("\t"); // the path follows the first tab and may itself contain any character, a newline included
112	    if (tab <= 0 || !/^160000 [0-9a-f]+ \d$/.test(entry.slice(0, tab))) continue; // only a gitlink can hide a repository
113	    if (undecodable(entry)) return `a submodule path below ${dir} is not valid UTF-8; it cannot be checked for a planted repository`;
114	    candidates.add(entry.slice(tab + 1));
115	  }
116	  // `--directory` keeps the listing short; Git collapses an untracked directory into one `dir/` entry, so a repository
117	  // planted anywhere below it is looked for on disk, within a budget.
118	  let budget = MAX_UNTRACKED_ENTRIES_SCANNED;
119	  // Git never reads a repository inside an ignored directory (`node_modules`) when it reports status: not scanned, not counted.
120	  const ignored = new Set(listing(["ls-files", "-o", "-i", "--exclude-standard", "--directory", "-z"]).filter((entry) => entry.endsWith("/")).map((entry) => path.join(dir, entry.slice(0, -1))));
121	  for (const entry of listing(["ls-files", "-o", "--exclude-standard", "--directory", "-z"])) {
122	    if (!entry.endsWith("/")) continue; // an ordinary untracked file, whatever its name, hides nothing
123	    if (undecodable(entry)) return `an untracked directory below ${dir} is not valid UTF-8; it cannot be checked for a planted repository`;
124	    const found = gitDirectoriesBelow(path.join(dir, entry), budget, ignored);
