51	export const WORKTREE_USAGE = "worktree [list|path <branch>|switch [-c] <branch> [--base B] [--no-copy]|remove <branch>... [--force] [--delete-unmerged]|copy-ignored [--from B] [--to B] [--force] [--dry-run] [--all-ignored]|merge [target] [--no-squash] [--no-rebase] [--no-remove] [-m message] [--no-verify-receipt --reason why] [--ai-message]|prune [--dry-run] [--min-age 1d] [--limit N] [--discard-ignored]]";
