175	function mergeOptionsFrom(parsed: Parsed): MergeOptions {
176	  return {
177	    target: parsed.positionals[0],
178	    noSquash: parsed.flags.has("no-squash"),
179	    noRebase: parsed.flags.has("no-rebase"),
180	    noRemove: parsed.flags.has("no-remove"),
181	    message: parsed.values.get("message"),
182	    noVerifyReceipt: parsed.flags.has("no-verify-receipt"),
