184	  };
185	}
186	
187	function formatCommandError(err: unknown): CommandResult {
188	  if (err instanceof WorktreeError || err instanceof WorktreePathError || err instanceof GitError) {
189	    return { success: false, output: redactSecrets(err.message) };
190	  }
191	  return { success: false, output: redactSecrets((err as Error)?.message ?? String(err)).slice(0, 400) };
192	}
193	
194	/** Split the text after the command name into tokens, preserving single- and double-quoted strings. */
195	export function tokenizeWorktreeArgs(args: string): string[] {
196	  const tokens: string[] = [];
197	  const regex = /"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|(\S+)/g;
198	  let match: RegExpExecArray | null;
199	  while ((match = regex.exec(args)) !== null) {
200	    if (match[1] !== undefined) {
201	      tokens.push(match[1].replace(/\\(["\\])/g, "$1"));
202	    } else if (match[2] !== undefined) {
203	      tokens.push(match[2].replace(/\\(['\\])/g, "$1"));
204	    } else if (match[3] !== undefined) {
205	      tokens.push(match[3]);
206	    }
207	  }
208	  return tokens;
209	}
210	
211	/**
212	 * Where an interactive session standing in a worktree that a command just removed should move to: the worktree of the
213	 * branch the work was merged into. Undefined when nothing was removed or the session is elsewhere.
214	 */
215	export function relocationAfter(result: CommandResult, cwd: string): string | undefined {
216	  const data = result.data as { removedPath?: string; targetPath?: string } | undefined;
217	  if (!result.success || !data?.removedPath || !data.targetPath) return undefined;
218	  const removed = data.removedPath;
219	  const inside = (candidate: string) => candidate === removed || candidate.startsWith(removed + path.sep);
220	  return inside(cwd) || inside(canonicalAfterRemoval(cwd)) ? data.targetPath : undefined;
221	}
222	
223	/** `realpath` for a path whose tail may be gone: resolves links (also dangling ones) and the deepest existing ancestor. */
224	function canonicalAfterRemoval(file: string, depth = 0): string {
225	  const absolute = path.resolve(file);
226	  try {
227	    return fs.realpathSync(absolute);
228	  } catch {
229	    if (depth > 20) return absolute;
230	    try {
231	      if (fs.lstatSync(absolute).isSymbolicLink()) return canonicalAfterRemoval(path.resolve(path.dirname(absolute), fs.readlinkSync(absolute)), depth + 1);
232	    } catch { /* not there at all */ }
233	    const parent = path.dirname(absolute);
234	    return parent === absolute ? absolute : path.join(canonicalAfterRemoval(parent, depth + 1), path.basename(absolute));
235	  }
236	}
237	
238	export interface AsyncDeps {
239	  /** Asks the configured model; absent when no provider is available. */
240	  completer?: Completer;
241	  aiTimeoutMs?: number;
242	  /** An operator cancel (Ctrl-C) while the model is being asked: the merge does not start. */
243	  signal?: AbortSignal;
244	}
245	
246	/** Like `runWorktreeCommand`, plus the opt-in `merge --ai-message`. Read-only mode never reaches the model. */
247	export async function runWorktreeCommandAsync(tokens: string[], run: RunContext, deps: AsyncDeps = {}): Promise<CommandResult> {
248	  const name = tokens[0] ? canonical(tokens[0]) : undefined;
249	  if (name !== "merge" || run.readOnly) return runWorktreeCommand(tokens, run);
250	  let parsed: Parsed;
251	  try { parsed = parse(SPECS.merge, tokens.slice(1)); } catch { return runWorktreeCommand(tokens, run); }
252	  if (!parsed.flags.has("ai-message") || parsed.values.has("message")) return runWorktreeCommand(tokens, run); // an explicit message wins
253	  if (parsed.positionals.length > 1) return runWorktreeCommand(tokens, run); // the one place that owns the merge usage
254	  const ctx: WorktreeContext = { cwd: run.cwd, home: run.home ?? homeDir(), readOnly: false };
255	
256	  const mergeOptions = mergeOptionsFrom(parsed);
257	  let mctx: MergeContextInfo;
258	  try {
259	    mctx = resolveMergeContext(ctx, mergeOptions);
260	  } catch (err) {
261	    return formatCommandError(err);
262	  }
263	
264	  const aiOptions: MergeOptions = { ...mergeOptions, amendSingleCommit: true };
265	  if (!writesCommitMessage(mctx, aiOptions)) {
266	    return runWorktreeCommand(tokens, run); // nothing to describe: the ordinary path
267	  }
268	
269	  if (deps.signal?.aborted) return { success: false, output: "Cancelled before the model was asked: nothing was merged, committed or removed." };
270	  const generated = await generateMergeMessage(mctx, deps.completer, deps.aiTimeoutMs ?? DEFAULT_AI_TIMEOUT_MS, deps.signal, mergeOptions);
271	
272	  if (deps.signal?.aborted) return { success: false, output: "Cancelled while the model was being asked: nothing was merged, committed or removed." };
273	
274	  try {
275	    const options: MergeOptions = { ...aiOptions, target: mctx.targetName, expectedState: { branch: mctx.branch, head: mctx.gateState.head, tree: mctx.gateState.tree }, ...(generated.message ? { message: generated.message } : {}) };
276	    const result = mergeWorktree(ctx, options);
277	    return { ...result, output: `${generated.note}\n${result.output}` };
278	  } catch (err) {
279	    return formatCommandError(err);
280	  }
281	}
