247	    if (!settings.allowOutside) {
248	      const real = fs.realpathSync(target);
249	      const realRoot = fs.realpathSync(root);
250	      if (real !== path.join(realRoot, path.relative(root, target))) {
251	        throw new WorktreeError("the new worktree resolved outside its allowed directory; inspect it with `git worktree list` before using it");
252	      }
253	    }
254	
255	    updateRegistry(repo.commonDir, (reg) => {
256	      reg.worktrees = reg.worktrees.filter((item) => item.path !== target && item.branch !== name);
257	      reg.worktrees.push({ branch: name, path: target, base: options.create ? baseName : name, createdAt: new Date().toISOString() });
258	      if (here?.branch && here.branch !== name) reg.previous = here.branch;
259	    });
260	    return { success: true, output: `Created worktree for ${shownBranch(name)} at ${shownPath(ctx.home, target)}`, data: { branch: name, path: target, created: true } };
261	  });
262	}
263	
264	function rememberPrevious(repo: Repo, from: string | null | undefined, to: string): void {
265	  if (!from || from === to) return;
266	  try { updateRegistry(repo.commonDir, (reg) => { reg.previous = from; }); } catch { /* the shortcut is a convenience */ }
267	}
268	
269	/** The worktree for `branch`, created from the default branch when neither it nor the branch exists (used by `run --worktree-branch`). */
270	export function ensureWorktree(ctx: WorktreeContext, branch: string): { branch: string; path: string; created: boolean } {
271	  const problem = validateBranchName(branch);
272	  if (problem) throw new WorktreeError(`invalid branch name: ${problem}`);
273	  const repo = openRepo(ctx.cwd);
274	  const exists = repo.entries.some((entry) => entry.branch === branch) || refExists(repo, `refs/heads/${branch}`);
275	  const result = switchWorktree(ctx, branch, { create: !exists });
276	  return result.data as { branch: string; path: string; created: boolean };
277	}
278	
279	// ---- path -----------------------------------------------------------------------------------------------------
280	
281	export function pathOf(ctx: WorktreeContext, token: string): CommandResult {
282	  const repo = openRepo(ctx.cwd);
283	  const entry = findEntry(repo, token, ctx.home);
284	  return { success: true, output: entry.path, data: { path: entry.path, branch: entry.branch } };
285	}
286	
287	// ---- list -----------------------------------------------------------------------------------------------------
288	
289	export interface ListItem {
290	  branch: string | null;
291	  path: string;
292	  head: string;
293	  main: boolean;
294	  current: boolean;
295	  detached: boolean;
296	  locked: boolean;
297	  prunable: boolean;
298	  kind: "main" | "task" | "named" | "external";
299	  registered: boolean;
300	  dirty: Dirty | null;
301	  ahead: number | null;
302	  behind: number | null;
303	  integrated: IntegratedReason | null;
304	  ageSeconds: number | null;
305	  /** Reserved for the activity marker (WP-1314). */
306	  agent: null;
307	  error?: string;
308	}
309	
310	export function listWorktrees(ctx: WorktreeContext, options: { limit?: number; json?: boolean } = {}): CommandResult {
311	  const repo = openRepo(ctx.cwd);
312	  const { registry, warning } = readRegistry(repo.commonDir);
313	  const here = currentEntry(repo);
314	  const limit = Math.max(1, options.limit ?? DEFAULT_LIMIT);
315	  const target = defaultBranch(repo);
316	  const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
317	
318	  const rank = (entry: WorktreeEntry) => (entry.isMain ? 0 : entry === here ? 1 : registry.worktrees.some((r) => r.path === entry.path) ? 2 : 3);
319	  const ordered = [...repo.entries].sort((a, b) => rank(a) - rank(b));
320	  const shown = ordered.slice(0, limit);
321	
322	  const now = Date.now() / 1000;
323	  const items: ListItem[] = shown.map((entry) => {
324	    const item: ListItem = {
325	      branch: entry.branch, path: entry.path, head: entry.head, main: entry.isMain, current: entry === here,
326	      detached: entry.detached, locked: entry.locked, prunable: entry.prunable, kind: kindOf(repo, entry, registry),
327	      registered: registry.worktrees.some((r) => r.path === entry.path), dirty: null, ahead: null, behind: null,
328	      integrated: null, ageSeconds: null, agent: null,
329	    };
330	    if (entry.prunable) { item.error = "directory is missing"; return item; }
331	    try {
332	      item.dirty = statusOf(entry.path);
333	      if (targetSha && entry.head) {
334	        const counts = gitOut(repo.cwd, ["rev-list", "--left-right", "--count", "--end-of-options", `${targetSha}...${entry.head}`], { timeoutMs: PER_CALL_MS }).split(/\s+/);
335	        item.behind = Number(counts[0]);
336	        item.ahead = Number(counts[1]);
337	        item.integrated = integratedReason(repo, entry.head, targetSha);
338	      }
339	      const stamp = Number(gitOut(repo.cwd, ["log", "-1", "--format=%ct", "--end-of-options", entry.head], { timeoutMs: PER_CALL_MS }));
340	      if (Number.isFinite(stamp)) item.ageSeconds = Math.max(0, Math.round(now - stamp));
341	    } catch (err) {
342	      item.error = (err as Error).message.slice(0, 120);
343	    }
344	    return item;
345	  });
346	
347	  // Machine output (`--json`, like `path`) carries branch names and paths as they are; only the human-readable
348	  // rendering below redacts them (docs/WORKTREES.md, "Safety").
349	  const data = {
350	    schema: LIST_SCHEMA,
351	    repo: { name: repo.repoName, path: repo.repoPath },
352	    defaultBranch: target ?? null,
353	    total: repo.entries.length,
354	    truncated: repo.entries.length > shown.length,
355	    ...(warning ? { warning } : {}),
356	    items,
357	  };
358	  if (options.json) return { success: true, output: JSON.stringify(data), data };
359	
360	  const lines = items.map((item) => {
361	    const mark = item.current ? "@" : item.main ? "^" : " ";
362	    const dirty = item.dirty ? (item.dirty.total ? `+${item.dirty.staged} ~${item.dirty.modified} ?${item.dirty.untracked}${item.dirty.conflicted ? ` !${item.dirty.conflicted}` : ""}` : "clean") : "?";
363	    const track = item.ahead === null ? "" : `↑${item.ahead}↓${item.behind}`;
364	    const state = item.integrated ? `integrated(${item.integrated})` : "";
365	    const age = item.ageSeconds === null ? "" : humanAge(item.ageSeconds);
366	    return [mark, item.branch ? shownBranch(item.branch) : "(detached)", item.kind, dirty, track, state, age, shownPath(ctx.home, item.path), item.error ? `[${item.error}]` : ""].filter((part, i) => i < 2 || part !== "").join("  ");
367	  });
368	  if (data.truncated) lines.push(`... ${repo.entries.length - shown.length} more worktrees not shown (--limit ${repo.entries.length} to show all)`);
369	  if (warning) lines.push(`warning: ${warning}`);
370	  return { success: true, output: lines.join("\n"), data };
371	}
372	
373	function humanAge(seconds: number): string {
374	  if (seconds < 3600) return `${Math.max(1, Math.round(seconds / 60))}m`;
375	  if (seconds < 86400) return `${Math.round(seconds / 3600)}h`;
376	  return `${Math.round(seconds / 86400)}d`;
377	}
378	
379	// ---- remove ---------------------------------------------------------------------------------------------------
380	
381	export interface RemoveOptions {
382	  force?: boolean;
383	  deleteUnmerged?: boolean;
384	  /**
385	   * Remove even if ignored files (build caches) are present, but never over tracked, staged or untracked changes: they
386	   * are checked again under the removal lock. Unlike `force`, which skips every check.
387	   */
388	  discardIgnored?: boolean;
389	  /** The branch the work must be integrated into (default: the repository's default branch). `merge` passes its target. */
390	  target?: string;
391	}
392	
393	/** Test seam: runs after every refusal check and immediately before the worktree is removed. Not a hook point. */
394	export const removeSeams: {
395	  beforeLock?: (entry: WorktreeEntry) => void;
396	  beforeRemove?: (entry: WorktreeEntry) => void;
397	  afterGuardSwitch?: (entry: WorktreeEntry) => void;
398	  beforeGuardSwitch?: (entry: WorktreeEntry) => void;
399	  beforeGitRemove?: (entry: WorktreeEntry) => void;
400	  beforeBranchDeletion?: (entry: WorktreeEntry) => void;
401	} = {};
402	
403	export function removeWorktrees(ctx: WorktreeContext, tokens: string[], options: RemoveOptions = {}): CommandResult {
404	  if (tokens.length === 0) throw new WorktreeError("usage: worktree remove <branch|path>... [--force] [--delete-unmerged]");
405	  const lines: string[] = [];
406	  let success = true;
407	  for (const token of tokens) {
408	    try {
409	      lines.push(removeOne(ctx, token, options));
410	    } catch (err) {
411	      success = false;
412	      lines.push(`${shownBranch(token)}: ${redactSecrets((err as Error).message)}`);
413	    }
414	  }
415	  return { success, output: lines.join("\n") };
416	}
417	
418	/** Removes one worktree (and its branch) after the safety checks; returns a one-line report or throws. */
419	export function removeOne(ctx: WorktreeContext, token: string, options: RemoveOptions): string {
420	  const repo = openRepo(ctx.cwd);
421	  const registry = loadRegistry(repo);
422	  const entry = findEntry(repo, token, ctx.home);
423	  const label = entry.branch ? shownBranch(entry.branch) : shownPath(ctx.home, entry.path);
424	  if (entry.isMain) throw new WorktreeError("the main worktree cannot be removed");
425	  if (currentEntry(repo) === entry) throw new WorktreeError("you are inside this worktree; run the command from another directory");
426	  if (entry.locked) throw new WorktreeError("the worktree is locked; unlock it with `git worktree unlock` first");
427	  if (kindOf(repo, entry, registry) === "task" && !options.force) {
428	    throw new WorktreeError("this worktree belongs to a speculative run (/worktree discard); use --force to remove it anyway");
429	  }
430	
431	  const dropFromRegistry = () => updateRegistry(repo.commonDir, (reg) => { reg.worktrees = reg.worktrees.filter((item) => item.path !== entry.path); });
432	  const target = options.target ?? defaultBranch(repo);
433	  const targetSha = target ? resolveBranchCommit(repo, target) : undefined;
434	  const integrated = entry.head && targetSha ? integratedReason(repo, entry.head, targetSha) : null;
435	  if (!integrated && !options.deleteUnmerged) {
436	    throw new WorktreeError(`${entry.branch ? "branch" : "HEAD"} is not merged into ${target ? shownBranch(target) : "the default branch"}; merge it, or pass --delete-unmerged to discard its commits`);
437	  }
438	
439	  // The lock is taken before anything is deleted and held through the branch and registry bookkeeping, so a
440	  // concurrent `switch` (which holds it across its checkout) either finishes first or waits; a lock that cannot be
441	  // had fails here with the worktree, branch and registry untouched.
442	  let branchNote = "";
443	  let guardBranch = "";
444	  let guardHead = "";
445	  removeSeams.beforeLock?.(entry);
446	  withWorktreeLock(repo.commonDir, () => {
447	    // What was read before waiting for the lock may be out of date: another remover can have dropped this stale
448	    // registration and a `switch` recreated the path. Anything that differs from what was checked is not removed.
449	    const fresh = openRepo(repo.cwd).entries.find((candidate) => candidate.path === entry.path);
450	    if (!fresh) {
451	      dropFromRegistry();
452	      branchNote = " (it was already gone)";
453	      return;
454	    }
455	    if (fresh.prunable !== entry.prunable || fresh.head !== entry.head || fresh.branch !== entry.branch || fresh.locked) {
456	      throw new WorktreeError("the worktree changed while this command waited for the lock; nothing was removed. Run the command again");
457	    }
458	    if (entry.prunable) {
459	      // Only this registration goes: a bare `worktree prune` would drop every stale worktree and leave their
460	      // registry entries behind. `remove --force` accepts a missing directory and touches one admin entry.
461	      git(repo.cwd, ["worktree", "remove", "--force", "--end-of-options", entry.path]);
462	    } else {
463	      const before = verifiedWorktreeDir(repo, entry);
464	      if (!options.force) {
465	        const dirty = statusOf(entry.path, { ignored: true, ignoreSubmodules: "none" });
466	        if (dirty.total + (options.discardIgnored ? 0 : dirty.ignored) > 0) {
467	          throw new WorktreeError(`worktree has ${dirty.staged + dirty.modified} changed, ${dirty.untracked} untracked and ${dirty.ignored} ignored path(s); commit or clean them, or pass --force`);
468	        }
469	      }
470	      removeSeams.beforeRemove?.(entry);
471	      // A commit made here since the integration check (another session's `/commit`, an editor) must not be lost with
472	      // the directory: on a detached HEAD nothing else would keep it. A moved HEAD is checked again, or nothing is removed.
473	      const headNow = git(entry.path, ["rev-parse", "--verify", "HEAD"], { allowFailure: true }).stdout.trim();
474	      if (headNow && headNow !== entry.head) {
475	        if (!targetSha || !integratedReason(repo, headNow, targetSha)) {
476	          throw new WorktreeError("HEAD changed while the worktree was being checked and the new commit is not merged; nothing was removed. Run the command again");
477	        }
478	        entry.head = headNow;
479	      }
480	      // The directory must still be the one that was inspected: a swap for a link or another tree is refused.
481	      const after = identityOf(entry.path);
482	      if (!after || after.dev !== before.dev || after.ino !== before.ino) throw new WorktreeError("the worktree directory changed while it was being checked; nothing was removed");
483	      // A detached HEAD keeps a commit only in this worktree's own administrative state, which the removal deletes, and
484	      // commit writers never take this lock. Putting the worktree on a temporary branch first means a commit that lands
485	      // from here on advances that branch instead; it is deleted below only if it still points at the checked commit.
486	      if (!entry.branch) {
487	        guardBranch = `nexus-removed/${createHash("sha1").update(entry.path).digest("hex").slice(0, 10)}-${entry.head.slice(0, 8)}`;
488	        // The commit the guard must protect is the one verified above, never one read after the switch: a commit that
489	        // lands in between would otherwise be adopted as "expected" and the branch deleted over it.
490	        guardHead = entry.head;
491	        // A guard branch that already exists was left by an interrupted attempt (or is someone's branch with that name).
492	        // It is never reused, moved or deleted: the user decides, before anything here is changed.
493	        const existing = git(repo.cwd, ["rev-parse", "--verify", "--quiet", "--end-of-options", `refs/heads/${guardBranch}`], { allowFailure: true });
494	        if (existing.status === 0) {
495	          const name = guardBranch;
496	          const tip = existing.stdout.trim();
497	          guardBranch = "";
498	          throw new WorktreeError(`the branch ${name} already exists (at ${tip.slice(0, 12)}), left by an earlier interrupted removal of this worktree or created by someone else. Nothing was removed. Inspect it with \`git log ${name}\` and, once it holds nothing you need, delete it with \`git branch -D ${name}\`, then run the command again`);
499	        }
500	        removeSeams.beforeGuardSwitch?.(entry);
501	        const switched = git(entry.path, ["switch", "-c", guardBranch, "--end-of-options"], { allowFailure: true });
502	        if (switched.status !== 0) {
503	          guardBranch = "";
504	          throw new WorktreeError("could not protect the detached HEAD before removing it; nothing was removed");
505	        }
506	        removeSeams.afterGuardSwitch?.(entry);
507	        const nowHead = git(entry.path, ["rev-parse", "--verify", "HEAD"]).stdout.trim();
508	        // `git switch` is not atomic with a concurrent `git commit`: a commit can be written to the HEAD reflog while HEAD
509	        // ends up back at the checked commit. The reflog entry before the switch must be that commit too.
510	        const before = git(entry.path, ["rev-parse", "--verify", "--quiet", "HEAD@{1}"], { allowFailure: true });
511	        const reflogMismatch = before.status === 0 && before.stdout.trim() !== guardHead;
512	        if (nowHead !== guardHead || reflogMismatch) {
513	          const name = guardBranch;
514	          guardBranch = ""; // kept: it now holds the commit that landed
515	          throw new WorktreeError(`a commit landed while the detached HEAD was being protected (HEAD or its reflog moved); it is kept on the branch ${name} in ${shownPath(ctx.home, entry.path)}, with its reflog, and nothing was removed. Merge or delete that branch, then run the command again`);
516	        }
517	      }
518	      try {
519	        removeSeams.beforeGitRemove?.(entry);
520	        // `worktree remove` runs `git status` in the worktree and re-reads its `.git` pointer: verify it once more first.
521	        const unsafe = nestedRepositoryReason(entry.path);
522	        if (unsafe) throw new UntrustedCheckoutError(entry.path, unsafe, ["worktree", "remove"]);
523	        git(repo.cwd, ["worktree", "remove", ...(options.force ? ["--force"] : []), "--end-of-options", entry.path]);
524	      } catch (err) {
525	        // Git refused (an initialised submodule, a file that appeared): the worktree stays, so put it back on its
526	        // detached HEAD and drop the guard branch (unless a commit already moved it, then it is the only reference).
527	        if (guardBranch) {
528	          const back = git(entry.path, ["switch", "--detach", "--end-of-options", guardBranch], { allowFailure: true });
529	          if (back.status === 0) {
530	            deleteBranchAt(repo, guardBranch, git(entry.path, ["rev-parse", "--verify", "HEAD"]).stdout.trim());
531	          } else {
532	            throw new WorktreeError(`${(err as Error).message}; could not restore the detached HEAD, so ${shownPath(ctx.home, entry.path)} stays on the temporary branch ${guardBranch} (nothing is lost). To undo: git -C <that path> switch --detach, then git branch -D ${guardBranch}. Do that before running the command again, because a retry refuses while the branch exists`);
533	          }
534	        }
535	        throw err;
536	      }
537	    }
538	
539	    if (guardBranch) {
540	      branchNote = deleteBranchAt(repo, guardBranch, guardHead)
541	        ? ""
542	        : `; a commit landed after the last check and is kept on the branch ${guardBranch}`;
543	    }
544	    if (entry.branch && entry.branch !== target) {
545	      removeSeams.beforeBranchDeletion?.(entry);
546	      const stillCheckedOut = listAfter(repo).some((other) => other.branch === entry.branch);
547	      if (!stillCheckedOut) {
548	        // Only the commit that passed the integration check may be deleted. A commit made by another session in the
549	        // meantime (its `/commit`, for example) moves the branch, and `branch -D` would make it unreachable.
550	        branchNote = deleteBranchAt(repo, entry.branch, entry.head) ? " and deleted its branch" : "; its branch moved after it was checked and was kept";
551	      }
552	    }
553	    dropFromRegistry();
554	  });
555	  return `Removed worktree ${label}${branchNote}`;
556	}
557	
558	/**
559	 * Drops one stale (directory deleted by hand) worktree registration: `git worktree remove --force <path>` on that one
560	 * entry and its registry record, never a branch. Callers decide whether it is safe (see `prune`).
561	 */
562	export function clearStaleEntry(repo: Repo, entry: WorktreeEntry): void {
563	  removeSeams.beforeLock?.(entry);
564	  withWorktreeLock(repo.commonDir, () => {
565	    // Re-read under the lock, as removeOne does: a `switch` may have recreated the path while this waited, and a live
566	    // worktree must not be force-removed on the strength of an entry read earlier.
567	    const fresh = openRepo(repo.cwd).entries.find((candidate) => candidate.path === entry.path);
568	    if (fresh && (!fresh.prunable || fresh.head !== entry.head || fresh.branch !== entry.branch || fresh.locked)) {
569	      throw new WorktreeError("the worktree changed while this command waited for the lock; it was left alone");
570	    }
571	    if (fresh) git(repo.cwd, ["worktree", "remove", "--force", "--end-of-options", entry.path]);
572	    updateRegistry(repo.commonDir, (reg) => { reg.worktrees = reg.worktrees.filter((item) => item.path !== entry.path); });
573	  });
574	}
575	
576	/** Delete `refs/heads/<branch>` only while it still points at `expectedSha` (Git's compare-and-delete). */
577	function deleteBranchAt(repo: Repo, branch: string, expectedSha: string): boolean {
578	  // The all-zero id tells update-ref to skip the comparison, so it is never accepted as an expected value.
579	  if (!/^[0-9a-f]{40,64}$/.test(expectedSha) || /^0+$/.test(expectedSha)) return false;
580	  return git(repo.cwd, ["update-ref", "-d", "--end-of-options", `refs/heads/${branch}`, expectedSha], { allowFailure: true }).status === 0;
581	}
582	
583	function listAfter(repo: Repo): WorktreeEntry[] {
584	  return openRepo(repo.cwd).entries;
585	}
586	
587	/** The worktree directory must be a real directory (not a link) whose `.git` file points into this repository. */
588	function verifiedWorktreeDir(repo: Repo, entry: WorktreeEntry): { dev: number; ino: number } {
589	  const before = identityOf(entry.path);
590	  const stat = fs.lstatSync(entry.path);
591	  if (!before || stat.isSymbolicLink() || !stat.isDirectory()) throw new WorktreeError("the worktree path is not a plain directory; refusing to remove it");
592	  const dotGit = path.join(entry.path, ".git");
593	  const content = readSmallFile(dotGit, MAX_POINTER_BYTES); // the agent controls this path: no blocking or unbounded read
594	  if (content === undefined) throw new WorktreeError("the worktree has no plain .git file; refusing to remove it");
595	  const pointer = parseGitfilePointer(content); // as Git reads it: nothing trimmed
596	  // The pointer may be absolute or, with `worktree.useRelativePaths`, relative to the worktree directory. Either way
597	  // its canonical location must be an entry under this repository's common directory.
598	  const admin = pointer === undefined ? "" : normalizedPath(path.resolve(entry.path, pointer));
599	  if (!admin || !admin.startsWith(path.join(normalizedPath(repo.commonDir), "worktrees") + path.sep)) {
600	    throw new WorktreeError("the worktree does not belong to this repository's common directory; refusing to remove it");
601	  }
602	  // The admin directory must point back at this very `.git` file. A pointer into a sibling worktree's admin directory
603	  // is inside the common directory too, but removing through it would act on the sibling's registration.
604	  let back = "";
605	  try { back = fs.readFileSync(path.join(admin, "gitdir"), "utf8").trim(); } catch { /* checked below */ }
606	  if (!back || normalizedPath(path.resolve(admin, back)) !== normalizedPath(dotGit)) {
607	    throw new WorktreeError("the worktree's administrative directory does not point back at it; refusing to remove it");
608	  }
609	  return { dev: before.dev, ino: before.ino };
610	}
611	
612	/** The operator home: the same one config.ts reads policy from, so worktree settings never come from another file. */
613	export function homeDir(): string {
614	  return operatorConfigHome();
615	}
