6	/** A one-shot completer over the configured provider; egress policy and receipts apply inside `chatCompletion`. */
7	export function providerCompleter(config: HarnessConfig): Completer {
8	  // A session started inside a worktree takes a project `.env` from it, and that file is the agent's: an endpoint it chose
9	  // is not somewhere a branch diff may go on the operator's behalf. (The CLI command builds its configuration without the
10	  // project layer, so this never applies there.)
11	  if (chosenByProjectEnvironment("LOCAL_LLM_ENDPOINT") && projectSetting("LOCAL_LLM_ENDPOINT") === config.endpoint) return async () => undefined;
12	  return async (messages, signal) => {
13	    const client = new LocalLlmClient({ ...config, workspace: "", maxSteps: 1 }, { role: "commit-message" });
14	    const reply = await client.chatCompletion(messages, [], undefined, signal, "commit-message");
15	    return typeof reply.content === "string" ? reply.content : "";
16	  };
17	}
