19	/**
20	 * A completer whose configuration is built on first use. Only building the configuration is guarded (no provider or an
21	 * invalid setting means "no model": undefined); a failing request is not swallowed, so the caller can say it failed.
22	 * The `local-model` placeholder is resolved to the server's loaded model first, as the run and interactive entry points
23	 * do, because servers such as vLLM reject the placeholder.
24	 */
25	export function lazyProviderCompleter(build: () => HarnessConfig, make: (config: HarnessConfig) => Completer = providerCompleter): Completer {
26	  return async (messages, signal) => {
27	    let completer: Completer;
28	    try {
29	      completer = make(await autoDetectModel(build()));
30	    } catch {
31	      return undefined;
32	    }
33	    return completer(messages, signal);
34	  };
35	}
